import{_ as s,a0 as i,w as u,s as r,ao as c,I as o,x as p,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"Linux有问必答：如何使用tcpdump来捕获TCP SYN，ACK和FIN包 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何使用tcpdump来捕获TCP SYN，ACK和FIN包 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何使用tcpdump来捕获TCP SYN，ACK和FIN包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何使用tcpdump来捕获TCP SYN，ACK和FIN包 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140915 Linux FAQs with Answers--How to capture TCP SYN, ACK and FIN packets with tcpdump","title":"Linux有问必答：如何使用tcpdump来捕获TCP SYN，ACK和FIN包","tag":"201410","desc":""},"relativePath":"201410/20140915 Linux FAQs with Answers--How to capture TCP SYN, ACK and FIN packets with tcpdump.md","filePath":"[post].md"}'),d={name:"201410/20140915 Linux FAQs with Answers--How to capture TCP SYN, ACK and FIN packets with tcpdump.md"};function m(l,t,C,T,f,N){const e=i("Link");return u(),r("div",null,[t[11]||(t[11]=c(`<h1 id="linux有问必答-如何使用tcpdump来捕获tcp-syn-ack和fin包" tabindex="-1">Linux有问必答：如何使用tcpdump来捕获TCP SYN，ACK和FIN包 <a class="header-anchor" href="#linux有问必答-如何使用tcpdump来捕获tcp-syn-ack和fin包" aria-label="Permalink to “Linux有问必答：如何使用tcpdump来捕获TCP SYN，ACK和FIN包”">​</a></h1><blockquote><p><strong>问题</strong>：我想要监控TCP连接活动（如，建立连接的三次握手，以及断开连接的四次握手）。要完成此事，我只需要捕获TCP控制包，如SYN，ACK或FIN标记相关的包。我怎样使用tcpdump来仅仅捕获TCP SYN，ACK和/或FYN包？</p></blockquote><p>作为业界标准的捕获工具，tcpdump提供了强大而又灵活的包过滤功能。作为tcpdump基础的libpcap包捕获引擎支持标准的包过滤规则，如基于5重包头的过滤（如基于源/目的IP地址/端口和IP协议类型）。</p><p>tcpdump/libpcap的包过滤规则也支持更多通用分组表达式，在这些表达式中，包中的任意字节范围都可以使用关系或二进制操作符进行检查。对于字节范围表达，你可以使用以下格式：</p><pre><code>proto [ expr : size ]
</code></pre><p>“proto”可以是熟知的协议之一（如ip，arp，tcp，udp，icmp，ipv6），“expr”表示与指定的协议头开头相关的字节偏移量。有我们熟知的直接偏移量如tcpflags，也有取值常量如tcp-syn，tcp-ack或者tcp-fin。“size”是可选的，表示从字节偏移量开始检查的字节数量。</p><p>使用这种格式，你可以像下面这样过滤TCP SYN，ACK或FIN包。</p><p>只捕获TCP SYN包：</p><pre><code> # tcpdump -i &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-syn) != 0&quot; 
</code></pre><p>只捕获TCP ACK包：</p><pre><code># tcpdump -i &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-ack) != 0&quot;
</code></pre><p>只捕获TCP FIN包：</p><pre><code># tcpdump -i &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-fin) != 0&quot;
</code></pre><p>之捕获TCP SYN或ACK包：</p><pre><code> # tcpdump -r &lt;interface&gt; &quot;tcp[tcpflags] &amp; (tcp-syn|tcp-ack) != 0&quot; 
</code></pre><p><img src="https://farm4.staticflickr.com/3923/15050566798_db14aea9a9_z.jpg" alt=""></p><hr>`,17)),o("p",null,[t[1]||(t[1]=p("via: ",-1)),a(e,{href:"http://ask.xmodulo.com/capture-tcp-syn-ack-fin-packets-tcpdump.html"},{default:n(()=>[...t[0]||(t[0]=[p("http://ask.xmodulo.com/capture-tcp-syn-ack-fin-packets-tcpdump.html",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=p("译者：",-1)),a(e,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[2]||(t[2]=[p("GOLinux",-1)])]),_:1}),t[5]||(t[5]=p(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[3]||(t[3]=[p("wxy",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=p("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[p("LCTT",-1)])]),_:1}),t[9]||(t[9]=p(" 原创翻译，",-1)),a(e,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[p("Linux中国",-1)])]),_:1}),t[10]||(t[10]=p(" 荣誉推出",-1))])])}const _=s(d,[["render",m]]);export{P as __pageData,_ as default};
